"#!/usr/bin/env python3
"""
Generate a complete OpenFOAM 10 (Foundation) buoyantFoam case in the
current working directory for a 3D Bernard-cell (Rayleigh-Benard)
convection simulation.

Domain  : 9 m (x) x 1 m (y) x 2 m (z)
Hot wall (y=0): 315 K, Cold wall (y=1): 295 K, others adiabatic.
Only files are written; no OpenFOAM commands are executed.
"""

import os

HEADER = """/*--------------------------------*- C++ -*----------------------------------*\\
  =========                 |
  \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox
   \\\\    /   O peration     | Website:  https://openfoam.org
    \\\\  /    A nd           | Version:  10
     \\\\/     M anipulation  |
\\*---------------------------------------------------------------------------*/
FoamFile
{{
    format      ascii;
    class       {cls};
    location    "{loc}";
    object      {obj};
}}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

"""

END = """// ************************************************************************* //\n"""


def hdr(obj, loc, cls="dictionary", dims=None, value=None, cc=None):
    s = HEADER.format(cls=cls, loc=loc, obj=obj)
    if dims is not None:
        s += "dimensions      %s;\n\n" % dims
    if value is not None:
        s += "value           %s;\n\n" % value
    return s


FILES = {}

# ---------------------------------------------------------------
# system/blockMeshDict
# ---------------------------------------------------------------
FILES["system/blockMeshDict"] = hdr("blockMeshDict", "system") + """scale   1;

vertices
(
    (0 0 0)
    (9 0 0)
    (9 1 0)
    (0 1 0)
    (0 0 2)
    (9 0 2)
    (9 1 2)
    (0 1 2)
);

blocks
(
    hex (0 1 2 3 4 5 6 7) (45 10 10) simpleGrading (1 1 1)
);

edges
(
);

boundary
(
    hotWall
    {
        type            wall;
        faces
        (
            (0 1 5 4)
        );
    }

    coldWall
    {
        type            wall;
        faces
        (
            (3 7 6 2)
        );
    }

    adiabaticWalls
    {
        type            wall;
        faces
        (
            (0 4 7 3)
            (1 2 6 5)
            (0 3 2 1)
            (4 5 6 7)
        );
    }
);

mergePatchPairs
(
);

""" + END

# ---------------------------------------------------------------
# system/controlDict
# ---------------------------------------------------------------
FILES["system/controlDict"] = hdr("controlDict", "system") + """application     buoyantFoam;

startFrom       latestTime;

startTime       0;

stopAt          endTime;

endTime         1000;

